const SECRET_HEADER = 'x-n8n-webhook-secret'

function readHeader(headers, name) {
  if (!headers || typeof headers !== 'object') return undefined
  const target = name.toLowerCase()
  for (const key of Object.keys(headers)) {
    if (key.toLowerCase() === target) {
      const value = headers[key]
      return Array.isArray(value) ? value[0] : value
    }
  }
  return undefined
}

const configuredSecret = $env.N8N_WEBHOOK_SECRET
const item = $input.first().json
const suppliedSecret = readHeader(item.headers || {}, SECRET_HEADER)

if (!configuredSecret) throw new Error('N8N_WEBHOOK_SECRET is not configured')
if (!suppliedSecret || suppliedSecret !== configuredSecret) {
  throw new Error('Invalid or missing webhook secret')
}

const body = item.body && typeof item.body === 'object' ? item.body : item
const dispute = body.dispute
const idempotencyKey = typeof body.idempotencyKey === 'string' ? body.idempotencyKey.trim() : ''

if (!idempotencyKey) throw new Error('idempotencyKey is required')
if (!dispute || typeof dispute !== 'object') throw new Error('dispute payload is required')

const recipient = typeof dispute.recipient === 'string' ? dispute.recipient.trim() : ''
const subject = typeof dispute.subject === 'string' ? dispute.subject.trim() : ''
const message = typeof dispute.body === 'string' ? dispute.body.trim() : ''
const disputeId = dispute.id

if (!Number.isInteger(disputeId) || disputeId <= 0) {
  throw new Error('dispute.id must be a positive integer')
}
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(recipient)) {
  throw new Error('dispute.recipient must be a valid email address')
}
if (!subject || subject.length > 255) {
  throw new Error('dispute.subject is required and must be 255 characters or fewer')
}
if (!message || message.length > 20000) {
  throw new Error('dispute.body is required and must be 20,000 characters or fewer')
}

const staticData = $getWorkflowStaticData('global')
if (!staticData.sentReceipts || typeof staticData.sentReceipts !== 'object') {
  staticData.sentReceipts = {}
}

const existing = staticData.sentReceipts[idempotencyKey]
if (existing) {
  return [{ json: Object.assign({}, existing, { idempotentReplay: true }) }]
}

return [{
  json: {
    idempotencyKey: idempotencyKey,
    disputeId: disputeId,
    recipient: recipient,
    subject: subject,
    message: message,
    idempotentReplay: false,
  },
}]

const validated = $('Validate Approved Dispute').first().json
const gmail = $input.first().json

const receipt = {
  success: true,
  idempotencyKey: validated.idempotencyKey,
  disputeId: validated.disputeId,
  recipient: validated.recipient,
  subject: validated.subject,
  messageId: gmail.id || null,
  threadId: gmail.threadId || null,
  provider: 'gmail',
  sentAt: new Date().toISOString(),
}

const staticData = $getWorkflowStaticData('global')
if (!staticData.sentReceipts || typeof staticData.sentReceipts !== 'object') {
  staticData.sentReceipts = {}
}
staticData.sentReceipts[receipt.idempotencyKey] = receipt

return [{ json: receipt }]
